/* procedure: fixdateandtime */
void fixdateandtime()
{
  systime = (12 * 60);
  sysday = 4;
  sysmonth = 7;
  sysyear = 1776;
  eqtb[5283].cint = systime;
  eqtb[5284].cint = sysday;
  eqtb[5285].cint = sysmonth;
  eqtb[5286].cint = sysyear;
  {
    time_t now = time(NULL);
    struct tm local_now;
#if defined(_POSIX_VERSION)
    localtime_r(&now, &local_now);
#else
    local_now = *localtime(&now);
#endif
    systime = local_now.tm_hour * 60 + local_now.tm_min;
    sysday = local_now.tm_mday;
    sysmonth = local_now.tm_mon + 1;
    sysyear = local_now.tm_year + 1900;
  }
}


